SELECT (SELECT COUNT(*) FROM information_schema.tables WHERE (table_schema='bk_auth' AND table_name IN ('user_account','auth_role')) OR (table_schema='bk_listing' AND table_name='listing_info') OR (table_schema='bk_memory' AND table_name IN ('user_preference_memory','system_constraint_memory')) OR (table_schema='bk_agent' AND table_name IN ('agent_event_audit','agent_async_workflow','agent_workflow_checkpoint')))=8;
